head.b:skin:
    /* =====================================================
       COLOR PALETTE
       ===================================================== */

    :root {
      --bg: #f1f1ee;
      --surface: #e8e8e4;
      --surface-hover: #deded9;

      --text: #303236;
      --text-muted: #777a7d;

      --border: #d4d4cf;

      --button-bg: #34373b;
      --button-text: #f1f1ee;

      --sidebar-bg: #e5e5e1;
      --sidebar-text: #303236;
    }

    html.dark-mode {
      --bg: #1c1e21;
      --surface: #25282c;
      --surface-hover: #2d3035;

      --text: #e2e3e5;
      --text-muted: #9b9ea3;

      --border: #383c42;

      --button-bg: #e2e3e5;
      --button-text: #202226;

      --sidebar-bg: #222529;
      --sidebar-text: #e2e3e5;
    }


    /* =====================================================
       RESET
       ===================================================== */

    * {
      box-sizing: border-box;
    }

    html {
      margin: 0;
      padding: 0;

      background: var(--bg);
      color: var(--text);

      transition:
        background-color 0.25s ease,
        color 0.25s ease;
    }

    body {
      margin: 0;
      padding: 0;

      background: var(--bg);
      color: var(--text);

      font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Roboto,
        Helvetica,
        Arial,
        sans-serif;

      transition:
        background-color 0.25s ease,
        color 0.25s ease;
    }

    a {
      color: inherit;
      text-decoration: none;
    }


    /* =====================================================
       FLOATING CONTROLS
       ===================================================== */

    .floating-controls {
      position: fixed !important;

      top: 20px !important;
      left: 20px !important;

      z-index: 9999 !important;

      display: flex !important;
      flex-direction: row !important;
      align-items: center !important;
      justify-content: flex-start !important;

      gap: 8px !important;

      width: auto !important;
      height: auto !important;

      margin: 0 !important;
      padding: 0 !important;
    }

    .floating-button {
      width: 42px !important;
      height: 42px !important;

      min-width: 42px !important;
      min-height: 42px !important;

      flex: 0 0 42px !important;

      display: flex !important;
      align-items: center !important;
      justify-content: center !important;

      margin: 0 !important;
      padding: 0 !important;

      border: 1px solid var(--border) !important;
      border-radius: 10px !important;

      background: var(--button-bg) !important;
      color: var(--button-text) !important;

      cursor: pointer;

      font-size: 18px;
      line-height: 1;

      box-shadow:
        0 3px 12px rgba(0, 0, 0, 0.12);

      transition:
        background-color 0.2s ease,
        color 0.2s ease,
        transform 0.2s ease;
    }

    .floating-button:hover {
      transform: translateY(-1px);
    }

    .floating-button:active {
      transform: translateY(0);
    }


    /* =====================================================
       SIDEBAR
       ===================================================== */

    .sidebar {
      position: fixed;

      top: 0;
      left: 0;

      width: 280px;
      height: 100vh;

      z-index: 9998;

      padding: 90px 24px 24px;

      background: var(--sidebar-bg);
      color: var(--sidebar-text);

      border-right: 1px solid var(--border);

      transform: translateX(-100%);

      transition:
        transform 0.25s ease,
        background-color 0.25s ease,
        color 0.25s ease;

      overflow-y: auto;
    }

    .sidebar.open {
      transform: translateX(0);
    }

    .sidebar-title {
      margin: 0 0 24px;

      font-size: 20px;
      font-weight: 600;
    }

    .sidebar-nav {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .sidebar-nav a {
      display: block;

      padding: 11px 12px;

      border-radius: 8px;

      color: var(--sidebar-text);

      transition:
        background-color 0.2s ease;
    }

    .sidebar-nav a:hover {
      background: var(--surface-hover);
    }


    /* =====================================================
       HEADER
       ===================================================== */

    .site-header {
      width: 100%;

      padding: 80px 24px 50px;

      text-align: center;
    }

    .site-title {
      margin: 0;

      color: var(--text);

      font-size: clamp(28px, 5vw, 44px);
      font-weight: 700;

      letter-spacing: -0.02em;
    }

    .site-title a {
      color: var(--text);
      text-decoration: none;
    }

    .site-title a:hover {
      color: var(--text);
    }

    .site-description {
      max-width: 650px;

      margin: 12px auto 0;

      color: var(--text-muted);

      font-size: 15px;
      line-height: 1.6;
    }


    /* =====================================================
       MAIN
       ===================================================== */

    .main-wrapper {
      width: calc(100% - 32px);
      max-width: 900px;
      margin-left: auto;
      margin-right: auto;
      min-height: 50vh;
    }

    .main-section {
      width: 100%;
    }

    .main-section > .widget {
      margin: 0;
    }


    /* =====================================================
       POST LIST
       ===================================================== */

    .posts-wrapper {
      width: 100%;
      max-width: 900px;
      margin-left: auto;
      margin-right: auto;
    }

    .posts-container {
      display: flex;
      flex-flow: row wrap;
      justify-content: space-evenly;
      align-items: stretch;
      gap: 16px;
      width: 100%;
      margin-left: auto;
      margin-right: auto;
    }

    .posts-container .post-preview {
      flex: 0 1 calc(50% - 8px);
      width: calc(50% - 8px);
      min-width: 0;
    }

    .posts-container .single-post {
      flex: 0 0 100%;
      width: 100%;
    }

    .post-preview {
      display: flex;

      width: 100%;
      min-height: 120px;

      border: 1px solid var(--border);
      border-radius: 12px;

      background: var(--surface);

      overflow: hidden;

      transition:
        background-color 0.2s ease,
        border-color 0.2s ease,
        transform 0.2s ease;
    }

    .post-preview {
      color: inherit;
      text-decoration: none;
      cursor: pointer;
    }

    .post-preview:hover {
      background: var(--surface-hover);

      transform: translateY(-1px);
    }


    /* =====================================================
       POST THUMBNAIL
       ===================================================== */

    .post-thumbnail {
      display: flex;
      align-items: center;
      justify-content: center;

      flex: 0 0 150px;

      width: 150px;
      height: 120px;

      overflow: hidden;

      background: var(--surface-hover);
    }

    .post-thumbnail img {
      display: block;

      width: 100%;
      height: 100%;

      object-fit: cover;
    }

    .post-body img,
    .post-body iframe,
    .post-body video {
      max-width: 100%;
    }

    .post-body img[loading='lazy'],
    .post-body iframe[loading='lazy'],
    .post-body video[loading='lazy'] {
      content-visibility: auto;
    }

    .post-thumbnail-empty {
      width: 100%;
      height: 100%;

      background: var(--surface-hover);
    }


    /* =====================================================
       POST INFORMATION
       ===================================================== */

    .post-preview-content {
      flex: 1;
      min-width: 0;

      display: flex;
      flex-direction: column;
      justify-content: center;

      padding: 20px 22px;
    }

    .post-preview-date {
      margin: 0 0 6px;

      color: var(--text-muted);

      font-size: 13px;
      line-height: 1.4;
    }

    .post-preview-title {
      margin: 0;

      color: var(--text);

      font-size: 19px;
      font-weight: 600;

      line-height: 1.35;

      overflow: hidden;
    }


    /* =====================================================
       SINGLE POST
       ===================================================== */

    .single-post {
      width: 100%;

      padding: 30px;

      border: 1px solid var(--border);
      border-radius: 12px;

      background: var(--surface);
    }

    .single-post-title {
      margin: 0 0 12px;

      color: var(--text);

      font-size: clamp(28px, 5vw, 42px);
      line-height: 1.2;
    }

    .single-post-date {
      margin-bottom: 30px;

      color: var(--text-muted);

      font-size: 14px;
    }

    .post-body {
      color: var(--text);

      font-size: 17px;
      line-height: 1.8;

      overflow-wrap: break-word;
    }

    .post-body img {
      max-width: 100%;
      height: auto;
    }

    .post-body iframe {
      max-width: 100%;
    }

    .post-body a {
      color: var(--text);

      text-decoration: underline;
      text-decoration-color: var(--text-muted);
    }


    /* =====================================================
       PAGINATION
       ===================================================== */

    .blog-pager {
      display: flex;

      align-items: center;
      justify-content: center;

      gap: 8px;

      margin: 32px 0 10px;

      flex-wrap: wrap;
    }

    .pager-button {
      display: inline-flex;

      align-items: center;
      justify-content: center;

      min-width: 38px;
      height: 38px;

      padding: 0 12px;

      border: 1px solid var(--border);
      border-radius: 8px;

      background: var(--surface);
      color: var(--text);

      font-size: 14px;

      transition:
        background-color 0.2s ease,
        color 0.2s ease;
    }

    .pager-button:hover {
      background: var(--surface-hover);
    }


    /* =====================================================
       FOOTER
       ===================================================== */

    .site-footer {
      width: 100%;

      margin-top: 80px;

      padding: 40px 24px;

      border-top: 1px solid var(--border);

      background: var(--surface);

      color: var(--text-muted);

      text-align: center;

      font-size: 14px;
      line-height: 1.6;
    }


    /* =====================================================
       MOBILE
       ===================================================== */

    @media (max-width: 600px) {

      .floating-controls {
        top: 14px !important;
        left: 14px !important;

        display: flex !important;
        flex-direction: row !important;
        align-items: center !important;

        gap: 8px !important;
      }

      .floating-button {
        width: 40px !important;
        height: 40px !important;

        min-width: 40px !important;
        min-height: 40px !important;

        flex: 0 0 40px !important;

        border-radius: 9px !important;
      }

      .sidebar {
        width: min(280px, 85vw);

        padding-top: 80px;
      }

      .site-header {
        padding:
          75px 20px 40px;
      }

      .main-wrapper {
        width: calc(100% - 24px);
        margin-left: auto;
        margin-right: auto;
      }

      .posts-container {
        flex-flow: row wrap;
        justify-content: space-evenly;
      }

      .posts-container .post-preview {
        flex: 0 1 100%;
        width: 100%;
      }

      .post-preview {
        min-height: 100px;
      }

      .post-thumbnail {
        flex: 0 0 105px;

        width: 105px;
        height: 100px;
      }

      .post-preview-content {
        padding: 14px 16px;
      }

      .post-preview-date {
        font-size: 12px;
      }

      .post-preview-title {
        font-size: 16px;
      }

      .single-post {
        padding: 22px 18px;
      }

      .post-body {
        font-size: 16px;
        line-height: 1.75;
      }

      .site-footer {
        margin-top: 60px;

        padding: 32px 20px;
      }

    }

body.script:
  //

    /* ===================================================
       MEDIA LAZY LOADING
       =================================================== */

    (function () {

      var lazyImages = document.querySelectorAll(
        '.post-body img'
      );

      var lazyFrames = document.querySelectorAll(
        '.post-body iframe'
      );

      var lazyVideos = document.querySelectorAll(
        '.post-body video'
      );


      /* Native lazy loading for media that supports it. */

      for (var i = 0; i < lazyImages.length; i++) {
        lazyImages[i].setAttribute('loading', 'lazy');
        lazyImages[i].setAttribute('decoding', 'async');
      }

      for (var j = 0; j < lazyFrames.length; j++) {
        lazyFrames[j].setAttribute('loading', 'lazy');
      }

      for (var k = 0; k < lazyVideos.length; k++) {
        lazyVideos[k].setAttribute('preload', 'none');
      }


      /*
       * For browsers where native lazy loading is not enough,
       * defer post-body media until it approaches the viewport.
       * We only touch post content, not Blogger's own iframes.
       */

      if ('IntersectionObserver' in window) {

        var observer = new IntersectionObserver(
          function (entries, obs) {

            for (var n = 0; n < entries.length; n++) {

              if (!entries[n].isIntersecting) {
                continue;
              }

              var element = entries[n].target;

              if (element.dataset.lazySrc) {
                element.src = element.dataset.lazySrc;
                element.removeAttribute('data-lazy-src');
              }

              var sources = element.querySelectorAll(
                'source[data-lazy-src]'
              );

              for (var m = 0; m < sources.length; m++) {
                sources[m].src = sources[m].dataset.lazySrc;
                sources[m].removeAttribute('data-lazy-src');
              }

              if (element.tagName.toLowerCase() === 'video') {
                element.load();
              }

              obs.unobserve(element);
            }

          },
          { rootMargin: '300px 0px' }
        );


        /*
         * Only move an iframe's existing src when it is a normal
         * post-body iframe. Blogger comment/tool iframes are outside
         * .post-body and therefore remain untouched.
         */

        for (var f = 0; f < lazyFrames.length; f++) {

          var frame = lazyFrames[f];

          if (frame.src && !frame.dataset.lazySrc) {
            frame.dataset.lazySrc = frame.src;
            frame.removeAttribute('src');
          }

          observer.observe(frame);
        }


        for (var v = 0; v < lazyVideos.length; v++) {

          var video = lazyVideos[v];

          var videoSources = video.querySelectorAll(
            'source[src]'
          );

          for (var q = 0; q < videoSources.length; q++) {
            videoSources[q].dataset.lazySrc = videoSources[q].src;
            videoSources[q].removeAttribute('src');
          }

          if (video.src) {
            video.dataset.lazySrc = video.src;
            video.removeAttribute('src');
          }

          observer.observe(video);
        }

      }

    })();


    (function () {

      var root =
        document.documentElement;

      var menuButton =
        document.getElementById('menu-toggle');

      var themeButton =
        document.getElementById('theme-toggle');

      var sidebar =
        document.getElementById('sidebar');


      /* ===================================================
         SIDEBAR TOGGLE
         =================================================== */

      if (menuButton && sidebar) {

        menuButton.addEventListener(
          'click',
          function () {

            sidebar.classList.toggle('open');

          }
        );

      }


      /* ===================================================
         DARK MODE
         =================================================== */

      var savedTheme =
        localStorage.getItem('blog-theme');


      if (savedTheme === 'dark') {

        root.classList.add('dark-mode');

      }


      function updateThemeIcon() {

        if (!themeButton) {
          return;
        }


        if (
          root.classList.contains('dark-mode')
        ) {

          themeButton.textContent = '\u2600';

          themeButton.setAttribute(
            'aria-label',
            'Switch to light mode'
          );

        } else {

          themeButton.textContent = '\u263E';

          themeButton.setAttribute(
            'aria-label',
            'Switch to dark mode'
          );

        }

      }


      updateThemeIcon();


      if (themeButton) {

        themeButton.addEventListener(
          'click',
          function () {

            root.classList.toggle(
              'dark-mode'
            );


            var isDark =
              root.classList.contains(
                'dark-mode'
              );


            localStorage.setItem(
              'blog-theme',
              isDark ? 'dark' : 'light'
            );


            updateThemeIcon();

          }
        );

      }

    })();

  //
